$ /bin/zsh -lc "python3 -B - <<'PY'
from pathlib import Path
import json
p=Path('/tmp/conclave-overhaul/wp1-icons/manifest-contract/proposed-manifest.json');d=json.loads(p.read_text())
contexts={
'microphone':{'mic.fill':'on control; reuse for unmuted status','mic.slash.fill':'muted control and muted badge'},
'camera':{'video.fill':'on control','video.slash.fill':'off control and camera-off status'},
'chat':{'message.fill':'control bar, closed or open; container/semantics express open','message':'lists and menus'},
'participants':{'person.2.fill':'header and control bar','person.2':'lists and menus'},
'raise_hand':{'hand.raised':'lowered control','hand.raised.fill':'raised control and raised badge'},
'share_screen':{'rectangle.on.rectangle':'idle Share screen control','rectangle.on.rectangle.slash':'active sharing stop control and host stop menu'},
'captions':{'captions.bubble':'off control or decorative transcript heading','captions.bubble.fill':'on control'},
'pin':{'pin':'Pin menu action','pin.slash':'Unpin menu action'},
'lock_meeting':{'lock.fill':'locked; host-lock or privacy badge','lock.open':'unlocked'},
'activities_games':{'square.grid.2x2':'Activities launcher','gamecontroller.fill':'games context'},
'warning_error_info':{'exclamationmark.triangle.fill':'warning next to text','exclamationmark.octagon.fill':'error next to text','info.circle':'information next to text'},
'copy_link':{'doc.on.doc':'ready Copy link action'},
}
for c in d['concepts']:
 for s in c['ios_symbols']:
  if s['context'].startswith('canonical:'):s['context']=contexts.get(c['id'],{}).get(s['name'],'canonical '+c['id']+' use; exact literal takes precedence over generic fill convention')
 for v in c['android_variants']:
  if c['id']=='participants':v['accessibility']['value']='participant and waiting counts; open selection semantics recommended with D02'
  if c['id']=='host':
   v['state']='host_badge';v['accessibility']['label']=None
 if c['id']=='host':
  c['android_variants'].append({'state':'host_controls_action','artwork_id':'shield_person.fill0','fill_basis':'recommendation','decision_id':'D01','references':[{'document':'S30','line':696}],'accessibility':{'label':'Host controls','value':None,'role':'button','icon_exposure':'decorative_in_labeled_owner'}})
 if c['id']=='search':
  c['android_variants'].append({'state':'search_action','artwork_id':'search.fill0','fill_basis':'recommendation','decision_id':'D01','references':[{'document':'F00','line':896}],'accessibility':{'label':'Search','value':None,'role':'button','icon_exposure':'decorative_in_labeled_owner'}})
 if c['id']=='lock_meeting':
  for v in c['android_variants']:v['accessibility']['role']='checkbox';v['references'].append({'document':'S50','line':908})
  # Host menu uses explicit checkbox semantics; shared binary state is not a mandated switch widget.
for a in d['artwork']:
 a['kotlin_property']=''.join(w.capitalize() for w in a['name'].split('_'))+'Fill'+str(a['fill'])
d['counts']['android_context_bindings']=sum(len(c['android_variants']) for c in d['concepts'])
d['accessibility_policy']['roles']='Roles describe use, not artwork. Host-menu Lock is Checkbox (S50:908); Switch rows keep Switch. Route rows are RadioButton with route label and selected state; route invoker is Button. Status badges never acquire an action from a reused glyph.'
d['accessibility_policy']['state_only_style']='Pressed, focused, disabled, unavailable, loading and unread/attention/count overlays reuse the same artwork; no new fill is implied. Native enabled/busy/selection/tooltip semantics belong to the owner.'
p.write_text(json.dumps(d,indent=2,ensure_ascii=False)+'\\n')
PY"
